import osfrom dotenv import load_dotenvfrom sqlalchemy.engine import URLload_dotenv()DATABASE_URL = URL.create(    drivername="mysql+pymysql",    username=os.environ["DB_USER"],    password=os.environ["DB_PASSWORD"],    host=os.getenv("DB_HOST", "localhost"),    port=int(os.getenv("DB_PORT", "3306")),    database=os.environ["DB_NAME"],    query={"charset": "utf8mb4"} #zabane farsi)from sqlalchemy import create_engineengine = create_engine(    DATABASE_URL,    echo=True,    pool_pre_ping=True)from sqlalchemy.orm import DeclarativeBaseclass Base(DeclarativeBase):    pass